sap.ui.define(["sap/ui/core/mvc/Controller","sap/ui/model/json/JSONModel"],function(s,e){"use strict";return s.extend("admindashboard.controller.AdminDashboard",{onInit:function(){var s=new e({totalAssets:0,assignedAssets:0,repairAssets:0,retiredAssets:0,archivedAssets:0,employees:0,vendors:0});this.getView().setModel(s,"kpi");this._loadKPIs()},_loadKPIs:async function(){try{const t=await fetch("/odata/v4/asset-admin/getDashboardKPIs",{method:"POST",headers:{"Content-Type":"application/json"}});const a=await t.json();this.getView().getModel("kpi").setData(a);var s=new e({items:[{Status:"Assigned",Count:a.assignedAssets},{Status:"Repair",Count:a.repairAssets},{Status:"Retired",Count:a.retiredAssets},{Status:"Archived",Count:a.archivedAssets}]});this.getView().setModel(s,"chart")}catch(s){console.error(s)}}})});